// GOOD CODE: This code uses PreparedStatement to prevent SQL Injection
// by using parameterized queries.
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureLogin {
    public boolean login(String username, String password) throws Exception {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");

        // Use a parameterized query with placeholders (?)
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";
        PreparedStatement pstmt = conn.prepareStatement(query);

        // Safely set parameters; the driver handles escaping and type safety
        pstmt.setString(1, username);
        pstmt.setString(2, password);

        ResultSet rs = pstmt.executeQuery();
        boolean loggedIn = rs.next();

        rs.close();
        pstmt.close();
        conn.close();

        return loggedIn;
    }
}
